167	
168			svc, ok := rm.Resource().Attributes().Get(string(conventions.ServiceNameKey))
169			if !ok {
170				errs = append(errs, fmt.Errorf("unable to get service name from resource metric with attributes: %v", rm.Resource().Attributes().AsRaw()))
171				continue
172			}
173	
174			newMD := pmetric.NewMetrics()
175			rmClone := newMD.ResourceMetrics().AppendEmpty()
176			rm.CopyTo(rmClone)
177	
178			key := svc.Str()
179			existing, ok := results[key]
180			if ok {
181				metrics.Merge(existing, newMD)
182			} else {
183				results[key] = newMD
184			}
185		}
186	
187		return results, errs
188	}
